import re, sys, json
def stmts(path):
    lines = open(path).read().split('\n')
    out = {}
    i = 0
    while i < len(lines):
        m = re.match(r'^(?:private )?(theorem|def|structure|inductive|abbrev) ([^\s(:{\[]+)', lines[i])
        if m:
            name = m.group(2)
            buf = [lines[i]]
            j = i
            if m.group(1) in ('theorem',):
                while ':=' not in lines[j] and j+1 < len(lines):
                    j += 1; buf.append(lines[j])
                s = '\n'.join(buf)
                s = s[:s.index(':=')]
            else:
                s = lines[i]
            out[name] = ' '.join(s.split())
            i = j + 1
        else:
            i += 1
    return out
a = stmts(sys.argv[1]); b = stmts(sys.argv[2])
for n in sorted(set(a) | set(b)):
    if n not in b: print('REMOVED', n, '::', a[n][:300]); continue
    if n not in a: print('ADDED', n, '::', b[n][:400]); continue
    if a[n] != b[n]:
        print('CHANGED', n); print('  v0  :', a[n]); print('  v01 :', b[n])
